class Solution:
    def movesToMakeZigzag(self, nums):
        def cost(start):
            res = 0
            for i in range(start, len(nums), 2):
                m = float('inf')
                if i > 0:
                    m = min(m, nums[i - 1])
                if i + 1 < len(nums):
                    m = min(m, nums[i + 1])
                if nums[i] >= m:
                    res += nums[i] - m + 1
            return res
        return min(cost(0), cost(1))

