class Solution:
    def movesToMakeZigzag(self, nums):
        even = odd = 0
        n = len(nums)
        for i, x in enumerate(nums):
            m = min([v for v in (nums[i-1] if i > 0 else None,
                                 nums[i+1] if i + 1 < n else None) if v is not None],
                    default=float('inf'))
            if x >= m:
                d = x - m + 1
                if i % 2 == 0:
                    even += d
                else:
                    odd += d
        return min(even, odd)

